class JumpReLUSAE(torch.nn.Module):
    """Gemma Scope's JumpReLU SAE, loaded straight from its `.npz` of parameters."""

    def __init__(self, params):
        super().__init__()
        # Identity modules, present only so their outputs are hookable.
        self.encode = WrapperModule()
        self.decode = WrapperModule()
        for name in ["W_enc", "b_enc", "W_dec", "b_dec", "threshold"]:
            setattr(self, name, torch.nn.Parameter(torch.from_numpy(params[name])))

    def features(self, x):
        """Feature activations. A plain method, so it also works outside a trace."""
        pre = x.to(self.W_enc.dtype) @ self.W_enc + self.b_enc
        return self.encode(torch.relu(pre) * (pre > self.threshold))

    def forward(self, x):
        acts = self.features(x)
        return self.decode(acts @ self.W_dec + self.b_dec).to(x.dtype)

import datasets

def build_corpus(tokenizer, n_seq, seq_len=128):
    """`n_seq` blocks of `seq_len` tokens from wikitext-103, each starting with BOS."""
    ds = datasets.load_dataset("Salesforce/wikitext", "wikitext-103-raw-v1", split="train")
    seqs, buffer = [], []
    for row in ds:
        if len(row["text"]) < 200:          # skip headings and blank lines
            continue
        buffer.extend(tokenizer(row["text"], add_special_tokens=False)["input_ids"])
        while len(buffer) >= seq_len - 1:
            seqs.append([tokenizer.bos_token_id] + buffer[:seq_len - 1])
            buffer = buffer[seq_len - 1:]
            if len(seqs) >= n_seq:
                return torch.tensor(seqs)
    return torch.tensor(seqs)

