class RawJumpReLUSAE(torch.nn.Module):
    """The same SAE written the obvious way: raw parameters, plain methods, no submodules."""

    def __init__(self, source):
        super().__init__()
        for name in ["W_enc", "b_enc", "W_dec", "b_dec", "threshold"]:
            setattr(self, name, torch.nn.Parameter(getattr(source, name).data))   # shares storage

    def encode(self, x):                                  # a method, not a module
        pre = x.to(self.W_enc.dtype) @ self.W_enc + self.b_enc
        return torch.relu(pre) * (pre > self.threshold)

    def forward(self, x):
        return (self.encode(x) @ self.W_dec + self.b_dec).to(x.dtype)

